---@type ReportValue
local ReportValue = T(Global, "ReportValue")

local handlers = {}

---@param player SBasePlayer|CBasePlayer
function handlers.onPlayerLogin(player)
    ReportValue.setValue(player.userId, "__login__", true)
end

---@param player SBasePlayer|CBasePlayer
function handlers.onPlayerLogout(player)
    local userId = player.userId
    LuaTimer:schedule(function()
        if PlayerManager:getPlayerByUserId(userId) then
            return
        end
        ReportValue.removeReportValueData(userId)
    end, 60000)
end

return function(name, ...)
    if type(handlers[name]) ~= "function" then
        return
    end
    handlers[name](...)
end